//! `key = value` settings.

use std::collections::BTreeMap;

/// A line that could not be read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConfigError {
    /// The 1-based line number.
    pub line: usize,
    /// What was wrong.
    pub message: String,
}

/// Settings from `key = value` lines; blank lines and `#` comments are skipped.
pub fn load(text: &str) -> Result<BTreeMap<String, String>, ConfigError> {
    let mut settings = BTreeMap::new();
    for (index, raw) in text.lines().enumerate() {
        if let Some((key, value)) = parse_line(raw, index + 1)? {
            settings.insert(key, value);
        }
    }
    Ok(settings)
}

/// `base` with each `key = value` line applied over it; unknown keys are refused.
pub fn apply(
    text: &str,
    base: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>, ConfigError> {
    let mut merged = base.clone();
    for (index, raw) in text.lines().enumerate() {
        let Some((key, value)) = parse_line(raw, index + 1)? else {
            continue;
        };
        if !merged.contains_key(&key) {
            return Err(ConfigError {
                line: index + 1,
                message: format!("unknown key {key}"),
            });
        }
        merged.insert(key, value);
    }
    Ok(merged)
}

/// `None` for a blank or `#` line, else the trimmed key and value split at the
/// first `=`.
pub fn parse_line(raw: &str, line: usize) -> Result<Option<(String, String)>, ConfigError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed.starts_with('#') {
        return Ok(None);
    }
    let Some((key, value)) = trimmed.split_once('=') else {
        return Err(ConfigError {
            line,
            message: "expected key = value".to_string(),
        });
    };
    Ok(Some((key.trim().to_string(), value.trim().to_string())))
}
